import { useState } from 'react';
import '@acme/ds/foundations.css';
import { Button, tokens } from '@acme/ds';

export function TaskScreen() {
  const [confirmingCancel, setConfirmingCancel] = useState(false);
  const [outcome, setOutcome] = useState<string | null>(null);

  const keepPlan = () => {
    setConfirmingCancel(false);
    setOutcome('Your plan stays as it is.');
  };

  return (
    <section
      aria-labelledby="plan-options-title"
      style={{
        background: tokens.color.surface.default,
        color: tokens.color.text.primary,
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--space-5)',
        padding: 'var(--space-6)',
        maxWidth: 560,
      }}
    >
      <h2 id="plan-options-title" style={{ margin: 0 }}>
        Manage your plan
      </h2>

      {/* Keep: the single primary action */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-3)' }}>
        <div>
          <strong>Keep your current plan</strong>
          <p style={{ margin: 0, color: tokens.color.text.secondary }}>
            Nothing changes. Your plan and billing stay the same.
          </p>
        </div>
        <div>
          <Button variant="primary" onClick={keepPlan}>
            Keep current plan
          </Button>
        </div>
      </div>

      {/* Downgrade: supporting alternative */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-3)' }}>
        <div>
          <strong>Switch to a cheaper plan</strong>
          <p style={{ margin: 0, color: tokens.color.text.secondary }}>
            Pay less each month. You can switch back at any time.
          </p>
        </div>
        <div>
          <Button variant="secondary" onClick={() => setOutcome('Choose a cheaper plan.')}>
            See cheaper plans
          </Button>
        </div>
      </div>

      {/* Cancel: low emphasis, equally visible and honest, not destructive (reversible) */}
      <div
        style={{
          display: 'flex',
          flexDirection: 'column',
          gap: 'var(--space-3)',
          paddingTop: 'var(--space-5)',
          borderTop: `1px solid ${tokens.color.text.secondary}`,
        }}
      >
        {!confirmingCancel ? (
          <div>
            <Button variant="ghost" onClick={() => setConfirmingCancel(true)}>
              Cancel subscription
            </Button>
          </div>
        ) : (
          <div
            role="group"
            aria-label="Confirm cancellation"
            style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-3)' }}
          >
            <p style={{ margin: 0 }}>
              Cancel your subscription? You can resubscribe whenever you like.
            </p>
            <div style={{ display: 'flex', gap: 'var(--space-3)' }}>
              <Button variant="secondary" onClick={keepPlan}>
                Never mind
              </Button>
              <Button
                variant="ghost"
                onClick={() => {
                  setConfirmingCancel(false);
                  setOutcome('Your subscription has been cancelled.');
                }}
              >
                Yes, cancel subscription
              </Button>
            </div>
          </div>
        )}
      </div>

      {outcome && (
        <p role="status" style={{ margin: 0 }}>
          {outcome}
        </p>
      )}
    </section>
  );
}

